class AdvancedTTLStore:
    """A TTL store that can also be scanned, swept, snapshotted and restored.

    It keeps the base contract: every method takes the current time, the
    expiration boundary is inclusive, and ttl=None means "never".
    """

    def __init__(self):
        # key -> (value, expires_at), where expires_at is None for "never".
        self._entries = {}

    def set(self, key, value, now, ttl=None):
        # One record per key, so an overwrite replaces the expiration too.
        expires_at = None if ttl is None else now + ttl
        self._entries[key] = (value, expires_at)

    def get(self, key, now):
        entry = self._entries.get(key)
        if entry is None:
            return None

        value, expires_at = entry
        if expires_at is not None and now >= expires_at:
            del self._entries[key]
            return None

        return value

    def delete(self, key, now):
        # Liveness first: deleting a key that has already expired is a no-op
        # and must report False rather than quietly succeeding.
        if self.get(key, now) is None:
            return False

        del self._entries[key]
        return True

    def purge(self, now):
        # The one place expired entries are dropped eagerly.
        expired = [
            key
            for key, (_, expires_at) in self._entries.items()
            if expires_at is not None and now >= expires_at
        ]
        for key in expired:
            del self._entries[key]
        return len(expired)

    def scan(self, prefix, now):
        # Sweep first, otherwise expired keys would sort into the result.
        self.purge(now)
        return sorted(
            (key, value)
            for key, (value, _) in self._entries.items()
            if key.startswith(prefix)
        )

    def snapshot(self, now):
        # Record remaining lifetime, not absolute expiry, so the snapshot is
        # still meaningful when it is restored at a different time. Rebuilding
        # each tuple is also what stops the snapshot aliasing the live store.
        self.purge(now)
        return {
            key: (value, None if expires_at is None else expires_at - now)
            for key, (value, expires_at) in self._entries.items()
        }

    def restore(self, snapshot, now):
        # Rebase each remaining lifetime onto the restore time.
        self._entries = {
            key: (value, None if ttl is None else now + ttl)
            for key, (value, ttl) in snapshot.items()
        }

