from bisect import bisect_left, bisect_right


class History:
    """Version history per key, with out-of-order writes and compaction.

    Each key keeps parallel sorted lists of timestamps and values, so a read
    is a binary search and a compaction is a single pass over that key.
    """

    def __init__(self):
        self.data = {}
        self.pins = set()

    def set(self, key, value, timestamp):
        times, values = self.data.setdefault(key, ([], []))
        i = bisect_left(times, timestamp)
        if i < len(times) and times[i] == timestamp:
            # Writing the same timestamp twice overwrites that version.
            values[i] = value
        else:
            times.insert(i, timestamp)
            values.insert(i, value)

    def get(self, key, timestamp):
        times, values = self.data.get(key, ([], []))
        # Rightmost timestamp at or before the query.
        i = bisect_right(times, timestamp) - 1
        return values[i] if i >= 0 else None

    def pin(self, timestamp):
        self.pins.add(timestamp)

    def unpin(self, timestamp):
        self.pins.discard(timestamp)

    def compact(self, cutoff):
        for key, (times, values) in list(self.data.items()):
            # Everything at or after the cutoff is always kept.
            keep = set(range(bisect_left(times, cutoff), len(times)))
            # Plus one boundary version below the cutoff, and one below each
            # pin. A pin usually falls in a gap, so the version *at or before*
            # it is what answers the query, not one written at it.
            for t in self.pins | {cutoff}:
                i = bisect_right(times, t) - 1
                if i >= 0:
                    keep.add(i)
            indices = sorted(keep)
            self.data[key] = (
                [times[i] for i in indices],
                [values[i] for i in indices],
            )

    def version_count(self, key):
        return len(self.data.get(key, ([], []))[0])

from collections import Counter


class CountStore:
    """A transactional key-value store that can also count values.

    Values are visible immediately, so the counts have to track reads and
    writes exactly. Every change is remembered per transaction so that a
    rollback can put the previous values back, and a commit hands the changes
    to the enclosing transaction rather than applying them outright.
    """

    def __init__(self):
        self.data = {}
        # value -> how many visible keys currently hold it.
        self.counts = Counter()
        # One dict of key -> previous value per open transaction.
        self.undo = []
        # A sentinel, because None is a legal value to store.
        self.missing = object()

    def get(self, key):
        return self.data.get(key)

    def count(self, value):
        return self.counts[value]

    def _write(self, key, value):
        """Set a key, keeping the counts in step. `missing` deletes it."""
        old = self.data.get(key, self.missing)
        if old is not self.missing:
            self.counts[old] -= 1
            # Drop the entry entirely so count(value) reports 0 cleanly.
            if not self.counts[old]:
                del self.counts[old]

        if value is self.missing:
            self.data.pop(key, None)
        else:
            self.data[key] = value
            self.counts[value] += 1

    def _remember(self, key):
        """Record a key's value before changing it, for a later rollback."""
        if self.undo:
            # setdefault, not assignment: the oldest recorded value is the one
            # a rollback has to restore.
            self.undo[-1].setdefault(key, self.data.get(key, self.missing))

    def set(self, key, value):
        self._remember(key)
        self._write(key, value)

    def delete(self, key):
        self._remember(key)
        self._write(key, self.missing)

    def begin(self):
        self.undo.append({})

    def commit(self):
        if not self.undo:
            raise ValueError('No transaction')
        changes = self.undo.pop()
        if self.undo:
            # Nested: hand the recorded previous values up to the parent, so
            # rolling the parent back still restores the original values.
            for key, old in changes.items():
                self.undo[-1].setdefault(key, old)

    def rollback(self):
        if not self.undo:
            raise ValueError('No transaction')
        # Replay in reverse, so two writes to one key unwind correctly.
        for key, old in reversed(list(self.undo.pop().items())):
            self._write(key, old)

