class WindowSet:
    """A changing set of covered, half-open time windows.

    The covered set is kept sorted, disjoint and non-touching at all times.
    That single invariant is what keeps add and remove cheap: a new interval
    can overlap at most one existing window on each side.
    """

    def __init__(self):
        self.data = []

    def windows(self):
        # A copy, so the caller cannot corrupt the internal invariant.
        return [r[:] for r in self.data]

    def add(self, start, end):
        # Union by merging the new interval into the sorted list.
        out = []
        for a, b in sorted(self.data + [[start, end]]):
            # <= so that touching windows merge as well as overlapping ones.
            if out and a <= out[-1][1]:
                out[-1][1] = max(out[-1][1], b)
            else:
                out.append([a, b])
        self.data = out

    def remove(self, start, end):
        out = []
        for a, b in self.data:
            if b <= start or a >= end:
                # Entirely outside the removed range.
                out.append([a, b])
            else:
                # Overlapping: keep whichever side survives, so one window
                # can legitimately become two.
                if a < start:
                    out.append([a, start])
                if b > end:
                    out.append([end, b])
        self.data = out

    def gaps(self, start, end):
        # Walk the covered windows once; everything not covered in between
        # is a gap.
        cursor = start
        out = []
        for a, b in self.data:
            if b <= cursor:
                continue
            if a >= end:
                break
            if a > cursor:
                out.append([cursor, min(a, end)])
            cursor = max(cursor, b)
        if cursor < end:
            out.append([cursor, end])
        return out

import unicodedata


class RankedAutocomplete:
    """Autocomplete that ranks by frequency and unifies equivalent spellings.

    Everything is stored in its normalised form, so two spellings of the same
    word are indistinguishable by the time they reach the dict.
    """

    def __init__(self):
        self.counts = {}

    def _norm(self, s):
        # NFC, then casefold, then NFC again. The trailing NFC is not
        # decoration: casefolding can decompose a character, and without
        # re-normalising the same word would land under two different keys.
        return unicodedata.normalize('NFC', unicodedata.normalize('NFC', s).casefold())

    def add(self, word, count=1):
        word = self._norm(word)
        self.counts[word] = self.counts.get(word, 0) + count

    def delete(self, word):
        word = self._norm(word)
        if word not in self.counts:
            return False
        del self.counts[word]
        return True

    def suggest(self, prefix, k):
        if k <= 0:
            return []
        prefix = self._norm(prefix)
        # Descending frequency, then ascending word, so a tie never depends
        # on insertion order.
        return sorted(
            (w for w in self.counts if w.startswith(prefix)),
            key=lambda w: (-self.counts[w], w),
        )[:k]

def token_plan(text, costs):
    """Return the cheapest segmentation, breaking ties on the token list.

    The cost pass keeps only numbers. Carrying token lists alongside them and
    comparing them at every position is quadratic, so the list is rebuilt in a
    second, linear pass.
    """
    # A trie, so candidate tokens at each position are found by walking rather
    # than by trying every known token.
    root = {}
    for word, cost in costs.items():
        node = root
        for ch in word:
            node = node.setdefault(ch, {})
        node[None] = (word, cost)

    n = len(text)
    # best[i] is the cheapest way to segment text[i:].
    best = [None] * (n + 1)
    best[n] = (0, [])

    for i in range(n - 1, -1, -1):
        node = root
        for j in range(i, n):
            if text[j] not in node:
                break
            node = node[text[j]]
            if None in node and best[j + 1] is not None:
                word, cost = node[None]
                suffix, plan = best[j + 1]
                candidate = (cost + suffix, [word] + plan)
                if best[i] is None or candidate < best[i]:
                    best[i] = candidate

    # Empty text costs 0 with no tokens; an unsegmentable text costs -1.
    return best[0] if best[0] is not None else (-1, [])

