from collections import deque


class EventTotals:
    """Idempotent aggregation with a bounded deduplication window.

    Two structures that age differently on purpose: the account totals are
    never pruned, while the record of which ids have been seen expires.
    """

    def __init__(self, retention):
        self.retention = retention
        self.ids = set()
        # (expiry time, id), so the left edge is the next to go.
        self.queue = deque()
        self.totals = {}

    def _expire(self, now):
        while self.queue and self.queue[0][0] <= now:
            _, id = self.queue.popleft()
            self.ids.remove(id)

    def accept(self, id, account, amount, now):
        self._expire(now)
        if id in self.ids:
            # A duplicate is refused outright, and deliberately does not
            # refresh the expiration: a client retrying in a loop would
            # otherwise hold its own id alive forever.
            return False
        self.ids.add(id)
        self.queue.append((now + self.retention, id))
        self.totals[account] = self.totals.get(account, 0) + amount
        return True

    def total(self, account):
        return self.totals.get(account, 0)

    def live_ids(self, now):
        self._expire(now)
        return len(self.ids)

