from collections import deque


def longest_span(events, k):
    """The longest contiguous span holding at most k distinct values."""
    if k <= 0:
        return 0, 0
    counts = {}
    left = 0
    best = (0, 0)
    for right, kind in enumerate(events):
        counts[kind] = counts.get(kind, 0) + 1
        # Shrink until the window is valid again. A kind dropping to zero
        # leaves the window entirely, which can make it valid and longer
        # without the right edge moving.
        while len(counts) > k:
            old = events[left]
            counts[old] -= 1
            if not counts[old]:
                del counts[old]
            left += 1
        # Strictly greater, so a tie keeps the smaller start.
        if right + 1 - left > best[1] - best[0]:
            best = (left, right + 1)
    return best


class TimeWindow:
    """Running counts over a half-open time window."""

    def __init__(self, window):
        self.window = window
        self.events = deque()
        self.totals = {}

    def _expire(self, now):
        # Half-open: an event at now - window has fallen out.
        while self.events and self.events[0][0] <= now - self.window:
            _, kind = self.events.popleft()
            self.totals[kind] -= 1
            if not self.totals[kind]:
                del self.totals[kind]

    def add(self, kind, now):
        self._expire(now)
        self.events.append((now, kind))
        self.totals[kind] = self.totals.get(kind, 0) + 1

    def counts(self, now):
        self._expire(now)
        # A copy, so the caller cannot corrupt the counts.
        return dict(self.totals)

