def retry_deadline(operation, attempts, base_delay, deadline, clock, sleep, jitter):
    """Retry with exponential backoff under a hard deadline.

    The clock, the sleep and the jitter are all injected, so nothing here
    really waits and the behaviour is fully deterministic in tests.
    """
    if attempts < 1:
        raise ValueError('Positive attempts required')

    for i in range(attempts):
        # Checked before each attempt, not during one: the deadline bounds
        # waiting, and there is no safe way to interrupt a call in flight.
        if clock() >= deadline:
            raise TimeoutError('deadline')
        try:
            # Returning the result directly is deliberate. None, 0, False and
            # the empty string are all successful answers, so the result's
            # truthiness must never decide whether this succeeded.
            return operation()
        except TimeoutError:
            if i == attempts - 1:
                # The last retryable failure re-raises the real error, so the
                # caller can see why it kept failing.
                raise
            delay = max(0, base_delay * 2 ** i + jitter(i))
            if clock() + delay >= deadline:
                # The wait could not help, so fail now rather than pause.
                raise TimeoutError('deadline')
            sleep(delay)

