import heapq


class HistoricalLedger:
    """A credit ledger that can answer questions about the past.

    Events arrive out of order and can even arrive long after the moment they
    describe, so a running total cannot be patched. Every query replays the
    events in their canonical order instead.
    """

    def __init__(self):
        self.events = []

    def grant(self, id, amount, time, ttl):
        # kind 0: grants sort before spends at the same instant, so a grant
        # made at time t is available to a spend made at time t.
        self.events.append((time, 0, id, amount, ttl))

    def spend(self, id, amount, time):
        self.events.append((time, 1, id, amount, None))

    def _replay(self, query):
        heap = []
        total = 0
        outcomes = {}

        for time, kind, id, amount, ttl in sorted(self.events):
            if time > query:
                break
            # Expire before this event, so a grant that has already lapsed
            # cannot be spent.
            while heap and heap[0][0] <= time:
                _, _, old = heapq.heappop(heap)
                total -= old

            if kind == 0:
                if amount:
                    heapq.heappush(heap, (time + ttl, id, amount))
                    total += amount
            else:
                outcomes[id] = amount <= total
                if amount > total:
                    # Refused: consume nothing at all.
                    continue
                total -= amount
                # Spend the earliest expiring grants first, lowest id first
                # among those expiring together, leaving partial grants.
                while amount:
                    expiry, gid, available = heapq.heappop(heap)
                    used = min(amount, available)
                    amount -= used
                    if available > used:
                        heapq.heappush(heap, (expiry, gid, available - used))

        # Grants that outlive the last event still expire before the query.
        while heap and heap[0][0] <= query:
            _, _, old = heapq.heappop(heap)
            total -= old

        return total, outcomes

    def balance(self, query_time):
        return self._replay(query_time)[0]

    def accepted(self, spend_id, query_time):
        # None when the spend had not happened by then, or is unknown.
        return self._replay(query_time)[1].get(spend_id)

