from collections import Counter, deque


class WindowErrors:
    """Exact top-k errors over a rolling time window."""

    def __init__(self, window):
        self.window = window
        # Arrival order, so the left edge can be dropped as time advances.
        self.events = deque()
        self.counts = Counter()

    def _expire(self, now):
        # The window is half-open: an event at now - window has fallen out.
        while self.events and self.events[0][0] <= now - self.window:
            _, error = self.events.popleft()
            self.counts[error] -= 1
            if self.counts[error] == 0:
                del self.counts[error]

    def add(self, error, now):
        self._expire(now)
        self.events.append((now, error))
        self.counts[error] += 1

    def top(self, k, now):
        self._expire(now)
        # Descending frequency, then ascending lexicographic, so the same data
        # always produces the same output.
        return sorted(self.counts, key=lambda e: (-self.counts[e], e))[:max(0, k)]


class HeavyHitters:
    """A bounded-memory heavy-hitter sketch (Misra-Gries).

    Counts are lower bounds on the true frequency. They are never exact and
    never an overestimate, which is the trade for holding at most `capacity`
    counters regardless of how many distinct errors arrive.
    """

    def __init__(self, capacity):
        self.capacity = capacity
        self.counts = {}

    def add(self, error):
        if error in self.counts:
            self.counts[error] += 1
        elif len(self.counts) < self.capacity:
            # Room for a new candidate.
            self.counts[error] = 1
        else:
            # Full. Decrement everyone and insert nothing, which is what
            # keeps a genuine heavy hitter above zero while rare items fall
            # out. Iterating a list copy allows deleting as we go.
            for key in list(self.counts):
                self.counts[key] -= 1
                if not self.counts[key]:
                    del self.counts[key]

    def candidates(self):
        return dict(self.counts)

class QueryIndex:
    """A document index answering boolean and phrase queries."""

    def __init__(self):
        self.docs = {}

    def add(self, doc_id, text):
        # lower().split() keeps punctuation, which documents and queries both
        # still contain. Splitting on word characters would drop symbols and
        # the two tokenisations would stop agreeing.
        # Re-adding a document replaces its content rather than merging.
        self.docs[doc_id] = text.lower().split()

    def all_of(self, query):
        terms = set(query.lower().split())
        return sorted(i for i, t in self.docs.items() if terms and terms <= set(t))

    def any_of(self, query):
        terms = set(query.lower().split())
        return sorted(i for i, t in self.docs.items() if terms & set(t))

    def without(self, query):
        terms = set(query.lower().split())
        # An empty query excludes nothing, so every document comes back.
        return sorted(i for i, t in self.docs.items() if not terms & set(t))

    def phrase(self, query):
        q = query.lower().split()
        if not q:
            return []
        # A phrase needs consecutive positions, not merely the presence of
        # every word. A set intersection would wrongly accept a document that
        # holds the tokens a thousand lines apart.
        return sorted(
            i
            for i, t in self.docs.items()
            if any(t[j:j + len(q)] == q for j in range(len(t) - len(q) + 1))
        )

