def gossip(node_ids, adjacency, phases):
    """Coordinated gossip: forward only what you learned in the previous phase.

    Full-set gossip is correct and pays for it on every round. Stamping each id
    with the phase it was learned in turns the payload into the delta, so a
    settled id crosses a link once and never again.
    """
    wired = neighbours(node_ids, adjacency)
    truth = component_sizes(node_ids, adjacency)
    # learned[node][id] = the phase in which that node first heard of id. The
    # stamp is the whole protocol: it says both what to send and when.
    learned = {node_id: {node_id: 0} for node_id in node_ids}
    sent = 0

    for phase in range(1, phases + 1):
        # Sends are cut from the state at the start of the phase, so nothing
        # learned during this phase can be forwarded within it.
        deltas = {
            node_id: {nid for nid, at in state.items() if at == phase - 1}
            for node_id, state in learned.items()
        }
        for source in node_ids:
            delta = deltas[source]
            for target in wired[source]:
                sent += len(delta)
                for nid in delta:
                    # Stamp on first hearing only, so the delta a node emits
                    # later is the set of ids it did not already have.
                    learned[target].setdefault(nid, phase)

    counts = {node_id: len(learned[node_id]) for node_id in node_ids}
    converged = all(counts[node_id] == truth.get(node_id) for node_id in node_ids)
    return {"counts": counts, "converged": converged, "sent": sent}


def neighbours(node_ids, adjacency):
    """Undirected neighbours per node; ids outside the cluster are ignored."""
    live = set(node_ids)
    links = {node_id: set() for node_id in node_ids}
    for node_id, adjacent in adjacency.items():
        if node_id not in live:
            continue
        for other in adjacent:
            if other in live:
                links[node_id].add(other)
                links[other].add(node_id)
    return links


def component_sizes(node_ids, adjacency):
    """Ground truth: the true size of the component each node belongs to."""
    links = neighbours(node_ids, adjacency)
    sizes = {}
    for start in node_ids:
        if start in sizes:
            continue
        seen = {start}
        stack = [start]
        while stack:
            for other in links[stack.pop()]:
                if other not in seen:
                    seen.add(other)
                    stack.append(other)
        for node_id in seen:
            sizes[node_id] = len(seen)
    return sizes

