class ReplayLog:
    """An append-only log whose recent tail can be replayed without a source.

    Replay replaces re-running the source: the last few items stay in
    memory, so restoring a recent position costs nothing. Everything older has
    fallen out, and that is the price of the bound.
    """

    def __init__(self, window):
        self.window = window
        self.held = []
        self.cursor = 0
        self.total = 0

    def spilled(self):
        # Memory only holds the tail, so this is how much history is gone.
        return max(0, self.total - self.window)

    def append(self, item):
        self.held.append(item)
        self.total += 1
        while len(self.held) > self.window:
            # The oldest item leaves memory but stays counted in total, which
            # is what keeps a position meaningful as an index into the log.
            self.held.pop(0)

    def snapshot(self):
        return self.cursor

    def _check(self, token):
        if token < self.spilled():
            # The item at this position no longer exists anywhere. Failing
            # loudly beats silently resuming from the wrong place.
            raise ValueError('position has been spilled')

    def restore(self, token):
        self._check(token)
        self.cursor = token

    def next(self, n):
        last = None
        for _ in range(n):
            index = self.cursor - self.spilled()
            if index < 0 or index >= len(self.held):
                return -1
            last = self.held[index]
            self.cursor += 1
        return last

    def replay(self, token):
        # A tee: it reads what follows a position without moving the cursor.
        self._check(token)
        return list(self.held[token - self.spilled():])

