import json
import zlib

CURRENT_VERSION = 2


def _from_v1(payload):
    if 'data' not in payload:
        raise ValueError('v1 payload has no data')
    return payload['data']


MIGRATIONS = {1: _from_v1}


class RecordCodec:
    """The base record format, unchanged. A log written by either version
    still reads, and framing below wraps whichever version it is."""

    CURRENT = CURRENT_VERSION

    def __init__(self, version=None):
        self.version = self.CURRENT if version is None else version

    def encode(self, state):
        return 'v%d %s' % (self.version, json.dumps(state, sort_keys=True))

    def decode(self, text):
        header, space, payload = text.partition(' ')
        if not space or not header.startswith('v'):
            raise ValueError('missing version header')
        try:
            version = int(header[1:])
        except ValueError:
            raise ValueError('unreadable version')
        if version > self.version:
            raise ValueError('unsupported version')
        data = json.loads(payload)
        while version < self.version:
            if version not in MIGRATIONS:
                raise ValueError('no migration from version %d' % version)
            data = MIGRATIONS[version](data)
            version += 1
        return data


def _crc(text):
    # Short and cheap: it catches a record that was damaged in place, which a
    # newline-delimited log cannot see. It is not a security property.
    return format(zlib.crc32(text.encode('utf-8')), '08x')


class CheckedJournal:
    """A journalled store whose every record carries its own checksum.

    The base journal could only spot a write that never finished. Framing each
    line with a checksum also catches one that finished and was then damaged,
    so the tail is verified rather than ignored. The position is now the
    sequence number of a record rather than a count of lines, which is what
    lets compaction move lines around without moving anyone's place.
    """

    def __init__(self, codec=None):
        self.codec = RecordCodec() if codec is None else codec
        self.log = []
        self.seq = 0

    def frame(self, record):
        payload = self.codec.encode(record)
        return _crc(payload) + ' ' + payload + '\n'

    def _write(self, record):
        # The sequence is assigned here and never reused, so a position names
        # a record instead of counting lines that compaction may replace.
        self.seq += 1
        self.log.append(self.frame(dict(record, seq=self.seq)))

    def append(self, key, value, now):
        self._write({'key': key, 'value': value, 'deleted': False, 'at': now})

    def remove(self, key, now):
        self._write({'key': key, 'value': None, 'deleted': True, 'at': now})

    def _split(self):
        lines = ''.join(self.log).split('\n')
        tail = lines.pop()
        if tail:
            # A frame always ends with a newline, so anything after the last
            # one is a torn write. There is no checksum for it to fail, and a
            # record nobody can vouch for is not a record.
            raise ValueError('unterminated frame')
        return lines

    def _entries(self, lines):
        for line in lines:
            if line.startswith('state '):
                # The compacted head written by compact(): a state as of a
                # sequence, marked so it cannot be read as a record.
                yield 'state', self.codec.decode(line[6:])
                continue
            checksum, _, payload = line.partition(' ')
            if not payload or _crc(payload) != checksum:
                raise ValueError('frame does not match its checksum')
            yield 'record', self.codec.decode(payload)

    def _apply(self, state, record):
        if record['deleted']:
            state.pop(record['key'], None)
        else:
            state[record['key']] = record['value']

    def _replay(self, lines, now, skip=0, base=None):
        state = {} if base is None else dict(base)
        for kind, payload in self._entries(lines):
            if kind == 'state':
                if payload['seq'] > skip:
                    # The compacted head stands in for everything at or below
                    # its sequence, so it replaces what was accumulated.
                    state = dict(payload['state'])
                continue
            if payload['seq'] <= skip:
                continue
            if payload['at'] > now:
                continue
            self._apply(state, payload)
        return state

    def load(self, now):
        return self._replay(self._split(), now)

    def snapshot(self, now):
        state = {}
        seq = 0
        for kind, payload in self._entries(self._split()):
            if kind == 'state':
                state = dict(payload['state'])
                seq = payload['seq']
                continue
            if payload['at'] > now:
                # Left for later, not skipped: a snapshot taken at an earlier
                # time still picks it up when restored at a later one.
                continue
            self._apply(state, payload)
            seq = payload['seq']
        return {'seq': seq, 'now': now, 'data': self.codec.encode(state)}

    def restore(self, snapshot, now):
        if now < snapshot['now']:
            raise ValueError('cannot restore to a time before the snapshot')
        # A position is an identity rather than a count of lines, so the log can
        # be rewritten underneath it. The snapshot is believed, not checked.
        return self._replay(
            self._split(),
            now,
            skip=snapshot['seq'],
            base=self.codec.decode(snapshot['data']),
        )

    def compact(self, snapshot, now):
        # One state line replaces everything at or below the sequence, and the
        # records past it are copied untouched. History below that sequence is
        # gone, so compact towards a snapshot you still intend to keep.
        lines = self._split()
        keep = [
            line + '\n'
            for line, (kind, payload) in zip(lines, self._entries(lines))
            if kind == 'record' and payload['seq'] > snapshot['seq']
        ]
        head = self.codec.encode(
            {
                'seq': snapshot['seq'],
                'state': self.codec.decode(snapshot['data']),
            }
        )
        self.log = ['state ' + head + '\n'] + keep
        return self.load(now)

