import re

ERROR = 'error'
FUNCTIONS = ('SUM', 'MIN', 'MAX', 'AVG', 'COUNT')
CELL = re.compile(r'([A-Za-z]+)([0-9]+)')
TOKEN = re.compile(r'[0-9]+(?:\.[0-9]+)?|[A-Za-z]+[0-9]*|[-+*/(),:]|\s+')
PRECEDENCE = {'+': 1, '-': 1, '*': 2, '/': 2}
BINARY = {'+': lambda a, b: a + b, '-': lambda a, b: a - b, '*': lambda a, b: a * b,
          '/': lambda a, b: ERROR if b == 0 else a / b}
AGGREGATE = {'SUM': sum, 'MIN': min, 'MAX': max, 'COUNT': len,
             'AVG': lambda values: sum(values) / len(values)}


def locate(ref):
    m = CELL.fullmatch(ref)
    if not m or int(m.group(2)) < 1:
        raise ValueError('Bad cell reference: ' + ref)
    col = 0
    for ch in m.group(1).upper():
        col = col * 26 + (ord(ch) - 64)
    return (int(m.group(2)), col)


def name_of(row, col):
    letters = ''
    while col > 0:
        col, digit = divmod(col - 1, 26)
        letters = chr(65 + digit) + letters
    return letters + str(row)


def _classify(text):
    if text[0] in '+-*/(),:':
        return 'op', text
    if '0' <= text[0] <= '9':
        return 'num', float(text) if '.' in text else int(text)
    return ('ref' if '0' <= text[-1] <= '9' else 'name'), text.upper()


def tokenize(source):
    raw = TOKEN.findall(source)
    if ''.join(raw) != source:
        raise ValueError('Unexpected character in: ' + source)
    return [_classify(text) for text in raw if text[0] not in ' \t\n\r']


class Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.i = 0
        self.refs = set()

    def peek(self):
        return self.tokens[self.i] if self.i < len(self.tokens) else None

    def take(self, kind=None, value=None):
        self.i += 1
        if self.i > len(self.tokens):
            raise ValueError('Formula ends early')
        token = self.tokens[self.i - 1]
        if kind is not None and token != (kind, value):
            raise ValueError('Expected ' + value)
        return token

    def expression(self, floor=1):
        node = self.unary()
        while (token := self.peek()) and PRECEDENCE.get(token[1], 0) >= floor:
            op = self.take()[1]
            node = ('bin', op, node, self.expression(PRECEDENCE[op] + 1))
        return node

    def unary(self):
        kind, value = self.take()
        if kind == 'num':
            return ('num', value)
        if kind == 'ref':
            return self.reference(value)
        if kind == 'name':
            return self.call(value)
        if value == '-':
            return ('bin', '*', ('num', -1), self.unary())
        if value != '(':
            raise ValueError('Unexpected token: ' + repr(value))
        node = self.expression()
        self.take('op', ')')
        return node

    def reference(self, ref):
        key = locate(ref)
        self.refs.add(key)
        if self.peek() != ('op', ':'):
            return ('ref', key)
        self.take()
        nxt = self.take()
        if nxt[0] != 'ref':
            raise ValueError('A range needs a second cell')
        span = (key, locate(nxt[1]))
        if span[0] > span[1]:
            raise ValueError('Reversed range: ' + ref + ':' + nxt[1])
        cells = [(row, col) for row in range(key[0], span[1][0] + 1)
                 for col in range(key[1], span[1][1] + 1)]
        self.refs.update(cells)
        return ('range', cells)

    def call(self, name):
        if name not in FUNCTIONS:
            raise ValueError('Unknown function: ' + name)
        self.take('op', '(')
        args = []
        while self.peek() and self.peek()[0] == 'ref':
            args.append(self.unary())
            if self.peek() != ('op', ','):
                break
            self.take()
        if not args:
            raise ValueError(name + ' takes a cell or range')
        self.take('op', ')')
        return ('call', name, args)


def parse(source):
    parser = Parser(tokenize(source))
    node = parser.expression()
    if parser.i != len(parser.tokens):
        raise ValueError('Trailing input in formula')
    return node, parser.refs


class BatchSheet:
    """The base engine plus the graph that says what a write invalidates.

    reads maps a cell to the cells its formula reads; users is the same edges
    backwards, so a write walks users and a cycle check walks reads.
    """

    def __init__(self):
        self.values, self.formulas = {}, {}
        self.reads, self.users = {}, {}
        self.recomputations = 0

    def get(self, cell):
        return self.values.get(locate(str(cell)), 0)

    def set(self, cell, value):
        self.set_many({cell: value})
        return self.get(cell)

    def order(self, changes):
        return [name_of(*cell) for cell in self._prepare(changes)[3]]

    def evaluate(self, formula):
        if not isinstance(formula, str) or not formula.startswith('='):
            raise ValueError('A formula starts with =')
        return self._eval(parse(formula[1:])[0])

    def set_many(self, changes):
        prepared, users, reads, order = self._prepare(changes)
        self.users, self.reads = users, reads
        for key, node, refs, value in prepared:
            self.formulas[key] = node
            if node is None:
                del self.formulas[key]
                self.values[key] = value
        for cell in order:
            self.values[cell] = self._eval(self.formulas[cell])
            self.recomputations += 1
        return len(order)

    def _prepare(self, changes):
        prepared = []
        for cell, value in changes.items():
            key = locate(str(cell))
            if isinstance(value, str) and value.startswith('='):
                node, refs = parse(value[1:])
            elif isinstance(value, (int, float)) and not isinstance(value, bool):
                node, refs = None, []
            else:
                raise ValueError('A cell holds a number or a formula')
            prepared.append((key, node, refs, value))

        users = {node: set(edge) for node, edge in self.users.items()}
        reads = dict(self.reads)
        for key, node, refs, value in prepared:
            for old in reads.get(key, ()):
                users[old].discard(key)
            if node is None:
                reads.pop(key, None)
            else:
                reads[key] = refs
            for ref in refs:
                users.setdefault(ref, set()).add(key)

        for key, node, refs, value in prepared:
            stack, reached = list(refs), set()
            while stack:
                cell = stack.pop()
                if cell == key:
                    raise ValueError('Circular reference: ' + name_of(*cell))
                if cell not in reached:
                    reached.add(cell)
                    stack.extend(reads.get(cell, ()))

        stack = [(seed, False) for seed in sorted(e[0] for e in prepared)]
        order, seen = [], set()
        while stack:
            node, ready = stack.pop()
            if ready:
                order.append(node)
            elif node not in seen:
                seen.add(node)
                if node in reads:
                    stack.append((node, True))
                stack.extend((u, False) for u in sorted(users.get(node, ())))
        # Reverse finish order is the topological order, so nothing is
        # published before the formula that feeds it.
        order.reverse()
        return prepared, users, reads, order

    def _eval(self, node):
        kind = node[0]
        if kind == 'num':
            return node[1]
        if kind == 'ref':
            return self.values.get(node[1], 0)
        if kind == 'range':
            return [self.values.get(cell, 0) for cell in node[1]]
        if kind == 'bin':
            left, right = self._eval(node[2]), self._eval(node[3])
            if left == ERROR or right == ERROR:
                return ERROR
            return BINARY[node[1]](left, right)
        values = []
        for arg in node[2]:
            flat = self._eval(arg)
            values += flat if isinstance(flat, list) else [flat]
        if ERROR in values:
            return ERROR
        return AGGREGATE[node[1]](values)

