RESERVED = 'key'


def rank_of(value):
    """Rank a column value into one total order.

    A row without a value gets a rank of its own and so never reaches the
    value comparison at all. Numbers rank before strings, which is what keeps
    a mixed column sorting instead of raising on the first int/str pair.
    """
    if value is None:
        return (0, 0, 0)
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        return (1, 0, value)
    return (1, 1, value)


def sort_key(row, column):
    # Ties fall back to the key, so two rows with the same column value always
    # come back in the same order no matter how they were written.
    return rank_of(row.get(column)) + (row[RESERVED],)


class GroupedStore:
    """The row store plus grouped queries.

    Aggregates are where answers start depending on the order writes arrived
    in rather than on the data. The fix is not to be careful: it is to build
    the grouping from the live rows and then sort the groups, so the same rows
    always report the same groups in the same order.
    """

    def __init__(self):
        self.rows = {}
        self.columns = {}

    def insert(self, table, row):
        if not isinstance(row, dict) or RESERVED not in row:
            raise ValueError('A row is a dict with a key column')
        key = row[RESERVED]
        if not isinstance(key, int) or isinstance(key, bool):
            raise ValueError('Keys are integers')
        for value in row.values():
            if value is not None and not isinstance(value, (int, float, str)):
                raise ValueError('Values are numbers, strings or None')
        self.rows.setdefault(table, {})[key] = (dict(row), False)
        self.columns.setdefault(table, set()).update(row)
        return dict(row)

    def update(self, table, key, changes):
        record = self.rows.get(table, {}).get(key)
        if record is None or record[1]:
            return None
        if RESERVED in changes:
            raise ValueError('The key column is fixed')
        seen = self.columns.get(table, ())
        for column in changes:
            if column not in seen:
                raise ValueError('Unknown column: ' + str(column))
        merged = dict(record[0])
        merged.update(changes)
        self.rows[table][key] = (merged, False)
        return dict(merged)

    def delete(self, table, key):
        record = self.rows.get(table, {}).get(key)
        if record is None or record[1]:
            return False
        self.rows[table][key] = (record[0], True)
        return True

    def select(self, table, where=None, order_by=None, desc=False, limit=None):
        if limit is not None and limit < 0:
            raise ValueError('limit is a nonnegative integer')
        rows = self._live(table, where)
        if order_by is None:
            rows.sort(key=lambda row: row[RESERVED])
        else:
            rows.sort(key=lambda row: sort_key(row, order_by))
        if desc:
            rows.reverse()
        if limit is not None:
            rows = rows[:limit]
        return rows

    def count(self, table, where=None):
        return len(self._live(table, where))

    def group_by(self, table, column, where=None):
        buckets = {}
        for row in self._live(table, where):
            # A row with no value for the column joins the None group, which
            # is why the bucket key is the value itself.
            buckets.setdefault(row.get(column), []).append(row)
        out = []
        for value in sorted(buckets, key=rank_of):
            group = buckets[value]
            group.sort(key=lambda row: row[RESERVED])
            out.append((value, [dict(row) for row in group]))
        return out

    def group_count(self, table, column, where=None):
        # Derived from group_by rather than counted separately, so the two can
        # never disagree about which rows belong to which group.
        return [
            (value, len(group))
            for value, group in self.group_by(table, column, where)
        ]

    def schema(self, table):
        return sorted(self.columns.get(table, ()))

    def _live(self, table, where=None):
        # Tombstones never reach an aggregate: a deleted row is not a row
        # with a missing value, it is not a row at all.
        rows = [
            row
            for row, deleted in self.rows.get(table, {}).values()
            if not deleted
        ]
        if where is None:
            return rows
        return [row for row in rows if where(row)]
